                                        .rounded(px(8.))
                                        .bg(p.amber_soft)
                                        .border_1()
                                        .border_color(p.amber.opacity(0.28))
                                        .flex()
                                        .flex_col()
                                        .gap(px(9.))
                                        .child(
                                            div()
                                                .flex()
                                                .items_center()
                                                .gap(px(7.))
                                                .text_size(px(12.5))
                                                .font_weight(FontWeight::MEDIUM)
                                                .text_color(p.amber_ink)
                                                .child(pro_icon(ProIcon::Clock, 13., p.amber_ink))
                                                .child(format!(
