                                                } else {
                                                    ProIcon::Copy
                                                },
                                                24.,
                                                copied_in,
                                                cx,
                                                move |this, _, cx| {
                                                    this.copy_payload(
                                                        CopySlot::Input,
                                                        in_json.clone(),
                                                        cx,
                                                    );
                                                },
                                            )),
                                    )
                                    .child(
                                        div()
                                            .p(px(11.))
                                            .rounded(px(8.))
                                            .bg(p.subtle)
                                            .border_1()
                                            .border_color(p.line)
                                            .font_family("Fira Code")
                                            .text_size(px(11.5))
                                            .line_height(px(18.))
                                            .text_color(p.ink)
                                            .child(call.input_json.clone()),
                                    ),
                            )
                            // Output JSON block
                            .child(
                                div()
                                    .flex()
                                    .flex_col()
                                    .gap(px(6.))
                                    .child(
                                        div()
                                            .flex()
                                            .items_center()
                                            .justify_between()
                                            .child(
                                                div()
                                                    .text_size(px(10.))
                                                    .font_weight(FontWeight::MEDIUM)
                                                    .text_color(p.muted)
                                                    .child(tr(
                                                        cx,
                                                        "RESPONSE PAYLOAD",
                                                        "响应结果 (JSON)",
                                                    )),
                                            )
                                            .child(pro_icon_btn(
                                                pro_eid(&self.id, "copy-output"),
                                                tr(cx, "Copy response JSON", "复制响应 JSON"),
                                                if copied_out {
                                                    ProIcon::Check
                                                } else {
                                                    ProIcon::Copy
                                                },
                                                24.,
                                                copied_out,
                                                cx,
                                                move |this, _, cx| {
                                                    this.copy_payload(
                                                        CopySlot::Output,
                                                        out_json.clone(),
                                                        cx,
                                                    );
                                                },
                                            )),
                                    )
                                    .child(
                                        div()
                                            .p(px(11.))
                                            .rounded(px(8.))
                                            .bg(p.subtle)
                                            .border_1()
                                            .border_color(p.line)
                                            .font_family("Fira Code")
                                            .text_size(px(11.5))
                                            .line_height(px(18.))
                                            .text_color(p.ink)
                                            .child(call.output_json.clone()),
                                    ),
                            )
                            // Collapsible Headers & Metadata
                            .child(
                                div()
                                    .flex()
                                    .flex_col()
                                    .child(activate(
                                        div()
                                            .id(pro_eid(&self.id, "toggle-headers"))
                                            .role(Role::Button)
                                            .tab_index(0)
                                            .h(px(24.))
                                            .rounded(px(5.))
                                            .hover(move |s| s.text_color(p.ink))
                                            .flex()
                                            .items_center()
                                            .gap(px(5.))
                                            .text_size(px(10.))
                                            .font_weight(FontWeight::MEDIUM)
                                            .text_color(p.muted)
                                            .cursor_pointer()
                                            .child(pro_icon(
                                                if self.headers_open {
                                                    ProIcon::ChevronDown
                                                } else {
                                                    ProIcon::ChevronRight
                                                },
                                                12.,
                                                p.faint,
                                            ))
                                            .child(tr(cx, "HEADERS & METADATA", "请求头与元数据")),
                                        cx,
                                        |this, _, cx| {
                                            this.headers_open = !this.headers_open;
                                            cx.notify();
                                        },
                                    ))
                                    .child(pro_fold(
                                        pro_eid(&self.id, "call-headers-fold"),
                                        self.headers_open,
                                        118.,
                                        0.,
                                        move || headers_rows.into_any_element(),
                                    )),
                            ),
                    ))
            }
        });

        let vtx_eid = pro_eid(&self.id, "floating-panel-vtx");
        pro_presence(
            pro_eid(&self.id, "floating-panel-pres"),
            panel_open && panel_opt.is_some(),
            0.22,
            0.16,
            move |amount| {
                let Some(panel_content) = panel_opt else {
                    return div().into_any_element();
                };
                let container = if is_sheet {
                    div()
                        .absolute()
                        .left(px(8.))
                        .right(px(8.))
                        .bottom(px(8. - 20. * (1. - amount)))
                        .h(px(420.))
                } else {
                    div()
                        .absolute()
                        .top(px(10.))
                        .right(px(10. - 24. * (1. - amount)))
                        .bottom(px(10.))
                        .w(px(384.))
                };
                container
                    .opacity(amount)
                    .rounded(px(12.))
                    .bg(p.card)
                    .border_1()
                    .border_color(p.line_strong)
                    .shadow_lg()
                    .overflow_hidden()
                    .on_mouse_down(MouseButton::Left, |_, _, cx| cx.stop_propagation())
                    .child(pro_view_transition_fill(
                        vtx_eid,
                        sel_vtx_key,
                        panel_content,
                    ))
                    .into_any_element()
            },
        )
    }

    fn render_mode_option(
        &self,
        suffix: &'static str,
        mode: ToolAccessMode,
        checked: bool,
        tool_id: SharedString,
        sensor: &ProSelectionSensor,
        cx: &Context<Self>,
    ) -> Stateful<Div> {
        let p = ProPalette::get(cx);
        let sensor_item = sensor.clone();
        let el = div()
            .id(pro_eid(&self.id, suffix))
            .role(Role::RadioButton)
            .tab_index(0)
            .relative()
            .flex_1()
            .h(px(26.))
            .rounded(px(6.))
            .hover(move |s| {
                if checked {
                    s.text_color(p.ink)
                } else {
                    s.text_color(p.ink).bg(p.hover)
                }
            })
            .text_size(px(12.5))
            .font_weight(if checked {
                FontWeight::MEDIUM
            } else {
                FontWeight::NORMAL
            })
            .text_color(if checked { p.ink } else { p.muted })
            .flex()
            .items_center()
            .justify_center()
            .cursor_pointer()
            .when(checked, |d| d.child(pro_mark_selected(&sensor_item)))
            .child(mode.label(cx));
        activate(el, cx, move |this, _, cx| {
            this.set_tool_mode(&tool_id, mode, cx);
        })
    }

    fn render_stats_quad(&self, cells: [(&str, String); 4], cx: &App) -> Div {
        let p = ProPalette::get(cx);
        div()
            .rounded(px(8.))
            .border_1()
            .border_color(p.line_strong)
            .flex()
            .flex_col()
            .child(
                div()
                    .flex()
                    .border_b_1()
                    .border_color(p.line)
                    .child(self.render_stat_cell(cells[0].0, &cells[0].1, true, cx))
                    .child(self.render_stat_cell(cells[1].0, &cells[1].1, false, cx)),
            )
            .child(
                div()
                    .flex()
                    .child(self.render_stat_cell(cells[2].0, &cells[2].1, true, cx))
                    .child(self.render_stat_cell(cells[3].0, &cells[3].1, false, cx)),
            )
    }

    fn render_stat_cell(&self, label: &str, value: &str, border_right: bool, cx: &App) -> Div {
        let p = ProPalette::get(cx);
        div()
            .flex_1()
            .min_w_0()
            .px(px(12.))
            .py(px(9.))
