    icon: ProIcon,
    title: impl Into<SharedString>,
    caption: impl Into<SharedString>,
    cta: Option<ProEmptyCta<V>>,
    cx: &Context<V>,
) -> Div {
    let p = ProPalette::get(cx);
    let mut box_el = div()
        .w_full()
        .py(px(48.))
        .px(px(24.))
        .flex()
        .flex_col()
        .items_center()
        .justify_center()
        .gap(px(10.))
        .child(
            div()
                .size(px(40.))
                .rounded(px(10.))
                .bg(p.chip)
                .border_1()
                .border_color(p.line)
                .flex()
                .items_center()
                .justify_center()
                .child(pro_icon(icon, 18., p.muted)),
        )
        .child(
            div()
                .text_size(px(14.))
                .font_weight(FontWeight::MEDIUM)
                .text_color(p.ink)
