        let rc = std::rc::Rc::new(handler);
        box_el = box_el.child(div().pt(px(4.)).child(pro_btn(
            id,
            label,
            None,
            ProBtnStyle::Secondary,
            true,
            cx,
            move |v, w, cx| (rc)(v, w, cx),
        )));
    }
    box_el
}

