            return;
        }
        if self.ghost_fade_out.is_some() {
            self.set_ghost("", cx);
        }
        self.value = value;
        self.caret = self.value.len();
        self.anchor = self.caret;
        self.marked = None;
        self.history.clear();
        self.redo.clear();
        self.changed(w, cx)
